import {controller} from '@github/catalyst'

@controller
class StaffbarUiVersionElement extends HTMLElement {
  async connectedCallback() {
    // Webpack global defined at build time
    if (typeof GIT_BRANCH !== 'undefined') {
      this.setText(GIT_BRANCH)
      return
    }

    // Vite dev-only dynamic import. In production the virtual module may not exist; swallow errors.
    if (BUNDLER === 'vite') {
      try {
        // eslint-disable-next-line import/no-unresolved
        const {gitBranch} = await import('vite:git-branch')
        this.setText(gitBranch)
      } catch {
        this.setText()
      }
    }
  }

  setText(branch?: string) {
    this.textContent = `UI: ${branch ?? 'unknown'}`
  }
}
